// Package keccaksimd computes Keccak-256 (Ethereum legacy padding 0x01, as in
// sha3.NewLegacyKeccak256) of many equal-length messages at once, one message per SIMD lane:
// AVX-512 8 lanes or AVX2 4 lanes on amd64 (kernels generated by _asm/main.go with avo).
// Without AVX2, and on other architectures, it falls back to golang.org/x/crypto/sha3.
package keccaksimd

import "golang.org/x/crypto/sha3"

const rate = 136

// HashMany sets out[i] = Keccak-256(msgs[i]). All messages must have the same length.
func HashMany(out [][32]byte, msgs [][]byte) {
	if len(out) != len(msgs) {
		panic("keccaksimd: len(out) != len(msgs)")
	}
	for _, m := range msgs {
		if len(m) != len(msgs[0]) {
			panic("keccaksimd: messages differ in length")
		}
	}
	if len(msgs) > 0 {
		hashMany(out, msgs)
	}
}

func hashGeneric(out [][32]byte, msgs [][]byte) {
	h := sha3.NewLegacyKeccak256()
	for i, m := range msgs {
		h.Reset()
		h.Write(m)
		h.Sum(out[i][:0])
	}
}

// HashBatch sets out[i] = Keccak-256(msgs[i]) for messages of any lengths: messages with the
// same number of full 136-byte blocks share lanes. idx is scratch (may be nil).
func HashBatch(out [][32]byte, msgs [][]byte, idx []int) []int {
	if len(out) != len(msgs) {
		panic("keccaksimd: len(out) != len(msgs)")
	}
	maxFull := 0
	same := true
	for _, m := range msgs {
		f := len(m) / rate
		maxFull = max(maxFull, f)
		if f != len(msgs[0])/rate {
			same = false
		}
	}
	if same {
		if len(msgs) > 0 {
			hashMany(out, msgs)
		}
		return idx
	}
	var gm [][]byte
	var go_ [][32]byte
	for f := 0; f <= maxFull; f++ {
		idx = idx[:0]
		for i, m := range msgs {
			if len(m)/rate == f {
				idx = append(idx, i)
			}
		}
		if len(idx) == 0 {
			continue
		}
		gm, go_ = gm[:0], go_[:0]
		for _, i := range idx {
			gm = append(gm, msgs[i])
		}
		go_ = append(go_, make([][32]byte, len(idx))...)
		hashMany(go_, gm)
		for j, i := range idx {
			out[i] = go_[j]
		}
	}
	return idx
}
